css_snippet:
body {
  font-family: "Inter", sans-serif;
  font-size: 16px;
  font-size-adjust: 0.54; /* Approximate aspect value for Inter */
}

h1 {
  font-family: "Lora", serif;
  font-size: 2.5em;
  /* Inherits font-size-adjust from body, adjusting Lora's x-height if it becomes the rendered font */
}

.secondary-text {
  font-family: "Montserrat", sans-serif;
  font-size: 1.1em;
  font-size-adjust: 0.54; /* Explicitly set to maintain visual balance with base font */
}
